import { ethers } from 'ethers';

'use client';

import { useState } from 'react';
import { useWallet } from '../hooks/useWallet';
import { ECONOMIC_PARAMS } from '../types';
import type { Deck, Card } from '../types';

export function DeckBuilder() {
  const { address, provider } = useWallet();
  const [myCards, setMyCards] = useState<Card[]>([]);
  const [selectedCards, setSelectedCards] = useState<string[]>([]);
  const [deckName, setDeckName] = useState('');
  const [building, setBuilding] = useState(false);
  const [deck, setDeck] = useState<Deck | null>(null);

  const handleCreateDeck = async () => {
    if (!provider || selectedCards.length === 0) return;
    setBuilding(true);
    try {
      await new Promise(r => setTimeout(r, 1000));
      setDeck({
        deckId: '0x' + Math.random().toString(16).slice(2, 34),
        owner: address,
        cardNodeIds: selectedCards,
        weights: selectedCards.map(() => 100),
        totalPotential: myCards.filter(c => selectedCards.includes(c.nodeId)).reduce((s, c) => s + c.potential, 0),
        createdAt: Date.now(),
        name: deckName || '我的牌组',
      });
      setSelectedCards([]);
      setDeckName('');
    } catch (e) {
      console.error(e);
    } finally {
      setBuilding(false);
    }
  };

  const toggleCard = (nodeId: string) => {
    setSelectedCards(prev =>
      prev.includes(nodeId) ? prev.filter(id => id !== nodeId) : [...prev, nodeId]
    );
  };

  return (
    <div className="p-4 border border-[#d4c5b0] rounded-lg bg-[#faf9f7]">
      <h2 className="text-lg font-medium mb-4 text-[#2a2522]">牌组编排</h2>

      <div className="mb-4 p-3 bg-[#f5f3ef] rounded text-sm text-[#6b5f56]">
        <div className="flex justify-between">
          <span>编排费</span><span className="font-medium">{ECONOMIC_PARAMS.ASSEMBLY_FEE} MEER</span>
        </div>
        <div className="flex justify-between mt-1">
          <span>最大卡数</span><span className="font-medium">30 张</span>
        </div>
      </div>

      <input
        type="text"
        value={deckName}
        onChange={e => setDeckName(e.target.value)}
        placeholder="牌组名称（选填）"
        className="w-full px-3 py-2 border border-[#d4c5b0] rounded text-sm mb-3 bg-white focus:outline-none focus:border-[#2a2522]"
      />

      <div className="mb-3">
        <div className="text-sm text-[#6b5f56] mb-2">选择卡牌（{selectedCards.length}/30）</div>
        {myCards.length === 0 ? (
          <div className="text-sm text-[#8b7a6b] text-center py-6 bg-[#f5f3ef] rounded">
            暂无卡牌，请先铸造
          </div>
        ) : (
          <div className="grid grid-cols-4 gap-2 max-h-48 overflow-y-auto">
            {myCards.map(card => (
              <button
                key={card.nodeId}
                onClick={() => toggleCard(card.nodeId)}
                className={`p-2 rounded border text-xs text-left transition-colors ${
                  selectedCards.includes(card.nodeId)
                    ? 'bg-[#2a2522] text-white border-[#2a2522]'
                    : 'bg-white text-[#6b5f56] border-[#d4c5b0] hover:border-[#2a2522]'
                }`}
              >
                <div className="font-medium truncate">{card.name}</div>
                <div className="text-[10px] opacity-70">⚡{card.potential}</div>
              </button>
            ))}
          </div>
        )}
      </div>

      <button
        onClick={handleCreateDeck}
        disabled={!address || selectedCards.length === 0 || building}
        className="w-full py-2.5 bg-[#2a2522] text-white rounded hover:bg-[#3d3632] transition-colors disabled:opacity-50 text-sm"
      >
        {building ? '编排中...' : `创建牌组 (${ECONOMIC_PARAMS.ASSEMBLY_FEE} MEER)`}
      </button>

      {deck && (
        <div className="mt-4 p-3 border border-[#d4c5b0] rounded bg-white">
          <div className="text-sm font-medium text-[#2a2522]">✅ {deck.name}</div>
          <div className="text-xs text-[#8b7a6b] mt-1">总势位: {deck.totalPotential}</div>
        </div>
      )}
    </div>
  );
}

import { ethers } from 'ethers';

'use client';

import { useState } from 'react';
import { useWallet } from '../hooks/useWallet';
import { ECONOMIC_PARAMS, REVENUE_SHARE, TIER_NAMES } from '../types';
import type { Battle, Deck, Distribution } from '../types';

export function BattleArena() {
  const { address, provider } = useWallet();
  const [myDecks, setMyDecks] = useState<Deck[]>([]);
  const [selectedDeck, setSelectedDeck] = useState<string>('');
  const [betAmount, setBetAmount] = useState(EVENT_PARAMS.BET_MIN);
  const [betting, setBetting] = useState(false);
  const [battles, setBattles] = useState<Battle[]>([]);

  const handleCreateBattle = async () => {
    if (!provider || !selectedDeck) return;
    setBetting(true);
    try {
      await new Promise(r => setTimeout(r, 1000));
      setBattles(prev => [{
        battleId: '0x' + Math.random().toString(16).slice(2, 34),
        player1: address,
        player2: '0x0000000000000000000000000000000000000000',
        deck1: selectedDeck,
        deck2: '',
        betAmount,
        winner: '',
        revenuePool: String(Number(betAmount) * 2),
        distributed: false,
        createdAt: Date.now(),
        endedAt: 0,
      }, ...prev]);
    } catch (e) {
      console.error(e);
    } finally {
      setBetting(false);
    }
  };

  const formatAddress = (addr: string) => addr ? `${addr.slice(0, 6)}...${addr.slice(-4)}` : '等待对手...';

  return (
    <div className="p-4 border border-[#d4c5b0] rounded-lg bg-[#faf9f7]">
      <h2 className="text-lg font-medium mb-4 text-[#2a2522]">对战竞技场</h2>

      <div className="mb-4 p-3 bg-[#f5f3ef] rounded text-sm text-[#6b5f56]">
        <div className="flex justify-between mb-1">
          <span>投注范围</span>
          <span className="font-medium">{ECONOMIC_PARAMS.BET_MIN} ~ {ECONOMIC_PARAMS.BET_MAX} MEER</span>
        </div>
        <div className="flex justify-between">
          <span>分账规则</span>
          <span className="font-medium">创作者 45% | 编排者 25%</span>
        </div>
      </div>

      <div className="mb-3 space-y-3">
        <div>
          <label className="block text-sm text-[#6b5f56] mb-1">选择牌组</label>
          <select
            value={selectedDeck}
            onChange={e => setSelectedDeck(e.target.value)}
            className="w-full px-3 py-2 border border-[#d4c5b0] rounded text-sm bg-white focus:outline-none focus:border-[#2a2522]"
          >
            <option value="">— 选择牌组 —</option>
            {myDecks.map(d => (
              <option key={d.deckId} value={d.deckId}>{d.name || d.deckId.slice(0, 8)} (⚡{d.totalPotential})</option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-sm text-[#6b5f56] mb-1">投注金额 (MEER)</label>
          <input
            type="number"
            value={betAmount}
            onChange={e => setBetAmount(e.target.value)}
            min={ECONOMIC_PARAMS.BET_MIN}
            max={ECONOMIC_PARAMS.BET_MAX}
            step="0.1"
            className="w-full px-3 py-2 border border-[#d4c5b0] rounded text-sm bg-white focus:outline-none focus:border-[#2a2522]"
          />
        </div>
      </div>

      <button
        onClick={handleCreateBattle}
        disabled={!address || !selectedDeck || betting}
        className="w-full py-2.5 bg-[#2a2522] text-white rounded hover:bg-[#3d3632] transition-colors disabled:opacity-50 text-sm"
      >
        {betting ? '发起中...' : `创建对战 (投注 ${betAmount} MEER)`}
      </button>

      {battles.length > 0 && (
        <div className="mt-4 space-y-3">
          <h3 className="text-sm font-medium text-[#6b5f56]">进行中的对战 ({battles.length})</h3>
          {battles.map(b => (
            <div key={b.battleId} className="p-3 border border-[#d4c5b0] rounded bg-white">
              <div className="flex justify-between items-center">
                <div className="text-xs text-[#8b7a6b]">
                  {formatAddress(b.player1)} vs {formatAddress(b.player2)}
                </div>
                <div className="text-sm font-medium text-[#2a2522]">{b.betAmount} MEER</div>
              </div>
              <div className="mt-1 text-xs text-[#8b7a6b]">
                奖池: {b.revenuePool} MEER | {b.distributed ? '已分账' : '待分账'}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

const EVENT_PARAMS = {
  BET_MIN: '0.1',
  BET_MAX: '10',
} as const;

'use client';

import { TIER_NAMES, TIER_BOUNDARIES, TIER_MULTIPLIERS } from '../types';
import type { Card } from '../types';

interface PotentialMapProps {
  cards: Card[];
}

export function PotentialMap({ cards }: PotentialMapProps) {
  const getTierColor = (tier: number) => {
    const colors = ['#a8937a', '#c0c0c0', '#ffd700', '#e5e4e2', '#b9f2ff', '#9966cc'];
    return colors[tier - 1] || colors[0];
  };

  return (
    <div className="p-4 border border-[#d4c5b0] rounded-lg bg-[#faf9f7]">
      <h2 className="text-lg font-medium mb-1 text-[#2a2522]">势位地图</h2>
      <p className="text-xs text-[#8b7a6b] mb-4">卡牌按势位档位分布</p>

      <div className="mb-4">
        <div className="flex gap-1 h-3 rounded-full overflow-hidden">
          {TIER_NAMES.map((name, i) => (
            <div
              key={name}
              className="flex-1 rounded-full"
              style={{ backgroundColor: getTierColor(i + 1) }}
              title={name}
            />
          ))}
        </div>
        <div className="flex justify-between mt-1 text-[10px] text-[#8b7a6b]">
          {TIER_BOUNDARIES.slice(0, -1).map((b, i) => (
            <span key={i}>{b}+</span>
          ))}
          <span>最高</span>
        </div>
      </div>

      {cards.length === 0 ? (
        <div className="text-center py-8 text-sm text-[#8b7a6b]">
          暂无卡牌数据
        </div>
      ) : (
        <div className="space-y-2 max-h-60 overflow-y-auto">
          {cards
            .sort((a, b) => b.potential - a.potential)
            .map(card => (
              <div
                key={card.nodeId}
                className="flex items-center gap-3 p-2 rounded border border-[#d4c5b0] bg-white hover:border-[#2a2522] transition-colors"
              >
                <div
                  className="w-3 h-3 rounded-full flex-shrink-0"
                  style={{ backgroundColor: getTierColor(card.tier) }}
                />
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-medium text-[#2a2522] truncate">{card.name}</div>
                  <div className="text-[10px] text-[#8b7a6b]">
                    {TIER_NAMES[card.tier - 1]} · 权重 {TIER_MULTIPLIERS[card.tier - 1]}x
                  </div>
                </div>
                <div className="text-right flex-shrink-0">
                  <div className="text-sm font-medium text-[#2a2522]">{card.potential}</div>
                  <div className="text-[10px] text-[#8b7a6b]">势位</div>
                </div>
              </div>
            ))}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useWallet } from '../hooks/useWallet';
import { CardMinter } from '../components/CardMinter';
import { DeckBuilder } from '../components/DeckBuilder';
import { BattleArena } from '../components/BattleArena';
import { PotentialMap } from '../components/PotentialMap';
import type { Card } from '../types';

type Tab = 'mint' | 'deck' | 'battle' | 'map';

export default function Home() {
  const { address, connecting, error, connect, disconnect } = useWallet();
  const [activeTab, setActiveTab] = useState<Tab>('mint');
  const [myCards, setMyCards] = useState<Card[]>([]);

  const tabs: { id: Tab; label: string }[] = [
    { id: 'mint', label: '铸造' },
    { id: 'deck', label: '编排' },
    { id: 'battle', label: '对战' },
    { id: 'map', label: '地图' },
  ];

  return (
    <div className="min-h-screen bg-[#faf9f7] text-[#2a2522]">
      {/* Header */}
      <header className="border-b border-[#d4c5b0] bg-white">
        <div className="max-w-3xl mx-auto px-4 py-3 flex items-center justify-between">
          <div>
            <h1 className="text-lg font-medium">⚡ 势位之战</h1>
            <p className="text-xs text-[#8b7a6b]">ECHO: Battle of Potential · MVP</p>
          </div>
          <div>
            {address ? (
              <div className="flex items-center gap-3">
                <span className="text-xs text-[#6b5f56] font-mono">
                  {address.slice(0, 6)}...{address.slice(-4)}
                </span>
                <button
                  onClick={disconnect}
                  className="text-xs px-3 py-1.5 border border-[#d4c5b0] rounded hover:border-[#2a2522] transition-colors"
                >
                  断开
                </button>
              </div>
            ) : (
              <button
                onClick={connect}
                disabled={connecting}
                className="text-xs px-4 py-1.5 bg-[#2a2522] text-white rounded hover:bg-[#3d3632] transition-colors disabled:opacity-50"
              >
                {connecting ? '连接中...' : '连接钱包'}
              </button>
            )}
          </div>
        </div>
      </header>

      {/* Error banner */}
      {error && (
        <div className="max-w-3xl mx-auto px-4 pt-3">
          <div className="p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700">{error}</div>
        </div>
      )}

      {/* Tab bar */}
      <div className="max-w-3xl mx-auto px-4">
        <div className="flex gap-1 border-b border-[#d4c5b0] mt-4">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`px-4 py-2 text-sm border-b-2 transition-colors ${
                activeTab === tab.id
                  ? 'border-[#2a2522] text-[#2a2522] font-medium'
                  : 'border-transparent text-[#8b7a6b] hover:text-[#2a2522]'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Content */}
      <main className="max-w-3xl mx-auto px-4 py-5">
        {activeTab === 'mint' && <CardMinter />}
        {activeTab === 'deck' && <DeckBuilder />}
        {activeTab === 'battle' && <BattleArena />}
        {activeTab === 'map' && <PotentialMap cards={myCards} />}
      </main>

      {/* Footer */}
      <footer className="max-w-3xl mx-auto px-4 py-6 text-center text-xs text-[#8b7a6b] border-t border-[#d4c5b0] mt-8">
        ECHO: Battle of Potential · Qitmeer Testnet · MVP Build
      </footer>
    </div>
  );
}

import type { Metadata } from 'next';
import './globals.css';

export const metadata: Metadata = {
  title: '势位之战 | ECHO: Battle of Potential',
  description: 'ECHO Battle of Potential MVP - Qitmeer',
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="zh">
      <body>{children}</body>
    </html>
  );
}

